// Generated from the fsaverage5 pial surface (FreeSurfer's average brain, MNI
// space, shipped with nilearn). Each point: x, y, z in mm (+128), region code,
// gyral brightness (from sulcal depth), surface normal x, y, z (+128). Lobes follow the standard landmarks: central sulcus,
// Sylvian fissure and parieto-occipital line. The cerebellum and brain stem,
// which the cortical mesh does not include, are approximated in place.
export const REGION_CODES = ["frontal", "parietal", "temporal", "occipital", "cerebellum", "stem"] as const;
export const POINT_COUNT = 13160;
export const POINTS_B64 = "";
export const HUBS = {'frontal': 10818, 'parietal': 1107, 'temporal': 6546, 'occipital': 2166, 'cerebellum': 11613} as const;
